affine_phase_pattern='(?:ConcreteRatchetKernel|SendStart|SendKdf|SendSeal|ReceiveEffect|ReceiveKdf|ReceiveOpen|ConcreteRatchetRestore|InitialRatchetKdfPending|InitialRatchetKdfResponse)'
